"""Manage llama-server as a subprocess owned by the engine process.

Desktop builds spawn args (catalog / ngl / parallel); the engine owns lifecycle,
GPU release before load, health wait, and idle stop — see docs/compute-ownership.md.
"""
from __future__ import annotations

import logging
import os
import signal
import subprocess
import threading
import time
import urllib.error
import urllib.request
from pathlib import Path
from typing import Any

_log = logging.getLogger("transub_engine.llm")

IDLE_STOP_MS = 5 * 60 * 1000
DEFAULT_PORT = 8080
_ALLOWED_EXE_NAMES = frozenset({"llama-server.exe", "llama-server"})


def _taskkill_tree(pid: int) -> None:
    if os.name != "nt":
        return
    try:
        subprocess.run(
            ["taskkill", "/pid", str(pid), "/T", "/F"],
            check=False,
            capture_output=True,
            creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0),
        )
    except Exception:
        pass


class LlamaServerManager:
    def __init__(self) -> None:
        self._lock = threading.RLock()
        self._proc: subprocess.Popen[bytes] | None = None
        self._state: dict[str, Any] | None = None
        self._log_tail = ""
        self._idle_timer: threading.Timer | None = None

    def get_log_tail(self, max_len: int = 800) -> str:
        with self._lock:
            return self._log_tail[-max_len:]

    def health(self) -> dict[str, Any]:
        with self._lock:
            running = self._proc is not None and self._proc.poll() is None
            state = dict(self._state) if self._state else None
            port = int(state.get("port") or 0) if state else 0
        healthy = False
        if running and port > 0:
            healthy = self._is_port_healthy(port, timeout_s=1.5)
            if not healthy and self._proc is not None and self._proc.poll() is not None:
                with self._lock:
                    self._proc = None
                    self._state = None
                running = False
        return {
            "ok": True,
            "running": bool(running),
            "healthy": bool(healthy and running),
            "modelId": (state or {}).get("modelId") or "",
            "port": port or None,
            "baseUrl": f"http://127.0.0.1:{port}" if port else None,
            "nGpuLayers": (state or {}).get("nGpuLayers"),
            "parallelSlots": (state or {}).get("parallelSlots"),
            "speculative": bool((state or {}).get("speculative")),
            "draftModelId": (state or {}).get("draftModelId") or "",
            "via": "engine",
        }

    def stop(self, *, reason: str = "") -> dict[str, Any]:
        with self._lock:
            self._clear_idle_timer_locked()
            had = self._proc is not None and self._proc.poll() is None
            self._kill_locked()
            self._state = None
            self._log_tail = ""
        if reason:
            _log.info("llama-server stopped reason=%s had=%s", reason, had)
        return {"ok": True, "stopped": bool(had), "via": "engine"}

    def clear_idle_stop(self) -> dict[str, Any]:
        with self._lock:
            self._clear_idle_timer_locked()
        return {"ok": True, "cancelled": True}

    def schedule_idle_stop(self, delay_ms: int | None = None) -> dict[str, Any]:
        delay = IDLE_STOP_MS if delay_ms is None else max(0, int(delay_ms))
        with self._lock:
            self._clear_idle_timer_locked()
            if delay <= 0:
                return {"ok": True, "cancelled": True}
            if self._proc is None or self._proc.poll() is not None:
                return {"ok": True, "scheduled": False, "reason": "not_running"}

            def _fire() -> None:
                try:
                    self.stop(reason="idle")
                except Exception:
                    _log.exception("idle stop failed")

            timer = threading.Timer(delay / 1000.0, _fire)
            timer.daemon = True
            self._idle_timer = timer
            timer.start()
        return {"ok": True, "scheduled": True, "delayMs": delay}

    def ensure(self, body: dict[str, Any]) -> dict[str, Any]:
        exe_path = str(body.get("exePath") or "").strip()
        args = body.get("args")
        model_id = str(body.get("modelId") or "").strip()
        port = int(body.get("port") or DEFAULT_PORT)
        after_asr = bool(body.get("afterAsr"))
        cwd = str(body.get("cwd") or "").strip()
        env_extra = body.get("env") if isinstance(body.get("env"), dict) else None
        health_timeout_ms = int(body.get("healthTimeoutMs") or 180000)
        idle_stop_ms = body.get("idleStopMs")

        err = self._validate_spawn(exe_path, args, port)
        if err:
            return err

        assert isinstance(args, list)
        arg_list = [str(a) for a in args]

        with self._lock:
            self._clear_idle_timer_locked()
            if (
                self._proc is not None
                and self._proc.poll() is None
                and self._state
                and self._state.get("modelId") == model_id
                and int(self._state.get("port") or 0) == port
                and self._is_port_healthy(port, timeout_s=2.0)
            ):
                out = {
                    "ok": True,
                    "already": True,
                    "modelId": model_id,
                    "model": model_id,
                    "baseUrl": f"http://127.0.0.1:{port}",
                    "apiKey": "local",
                    "port": port,
                    "nGpuLayers": self._state.get("nGpuLayers"),
                    "parallelSlots": self._state.get("parallelSlots") or 1,
                    "speculative": bool(self._state.get("speculative")),
                    "draftModelId": self._state.get("draftModelId") or "",
                    "via": "engine",
                }
                return out

            self._kill_locked()

        if after_asr:
            try:
                from .runtime_release import release_gpu_memory

                release_gpu_memory(reason="llm_ensure_after_asr", unload_models=True)
            except Exception as exc:
                _log.warning("release_gpu before llama failed: %s", exc)

        work_dir = cwd or str(Path(exe_path).resolve().parent)
        env = os.environ.copy()
        if env_extra:
            for k, v in env_extra.items():
                if k is None:
                    continue
                env[str(k)] = "" if v is None else str(v)

        creationflags = 0
        if os.name == "nt":
            creationflags = getattr(subprocess, "CREATE_NO_WINDOW", 0)

        log_chunks: list[str] = []

        def append_log(data: bytes) -> None:
            try:
                text = data.decode("utf-8", errors="replace")
            except Exception:
                text = str(data)
            log_chunks.append(text)
            joined = "".join(log_chunks)[-6000:]
            log_chunks.clear()
            log_chunks.append(joined)
            with self._lock:
                self._log_tail = joined

        try:
            proc = subprocess.Popen(
                [exe_path, *arg_list],
                cwd=work_dir,
                env=env,
                stdin=subprocess.DEVNULL,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                creationflags=creationflags,
            )
        except OSError as exc:
            return self._format_spawn_failure(exc, exe_path)

        def _reader(stream: Any) -> None:
            try:
                while True:
                    chunk = stream.read(4096)
                    if not chunk:
                        break
                    append_log(chunk)
            except Exception:
                pass

        threading.Thread(target=_reader, args=(proc.stdout,), daemon=True).start()
        threading.Thread(target=_reader, args=(proc.stderr,), daemon=True).start()

        with self._lock:
            self._proc = proc
            self._state = {
                "modelId": model_id,
                "port": port,
                "nGpuLayers": body.get("nGpuLayers"),
                "parallelSlots": body.get("parallelSlots") or 1,
                "speculative": bool(body.get("speculative")),
                "draftModelId": str(body.get("draftModelId") or ""),
                "exePath": exe_path,
            }

        healthy = self._wait_healthy(
            port,
            proc,
            timeout_ms=health_timeout_ms,
            get_tail=lambda: "".join(log_chunks),
        )
        if not healthy.get("ok"):
            with self._lock:
                self._kill_locked()
                self._state = None
            healthy["logTail"] = self.get_log_tail(1200)
            healthy["via"] = "engine"
            return healthy

        if idle_stop_ms is not None:
            self.schedule_idle_stop(int(idle_stop_ms))

        with self._lock:
            state = dict(self._state or {})
        return {
            "ok": True,
            "already": False,
            "modelId": model_id,
            "model": model_id,
            "baseUrl": f"http://127.0.0.1:{port}",
            "apiKey": "local",
            "port": port,
            "nGpuLayers": state.get("nGpuLayers"),
            "parallelSlots": state.get("parallelSlots") or 1,
            "speculative": bool(state.get("speculative")),
            "draftModelId": state.get("draftModelId") or "",
            "via": "engine",
        }

    def _validate_spawn(self, exe_path: str, args: Any, port: int) -> dict[str, Any] | None:
        if not exe_path:
            return {"ok": False, "error": "exePath required", "code": "exe_missing"}
        name = Path(exe_path).name.lower()
        if name not in {n.lower() for n in _ALLOWED_EXE_NAMES}:
            return {
                "ok": False,
                "error": "exePath must be llama-server",
                "code": "exe_rejected",
            }
        if not Path(exe_path).is_file():
            return {"ok": False, "error": "llama-server 可执行文件不存在", "code": "exe_missing"}
        if not isinstance(args, list) or not args:
            return {"ok": False, "error": "args required", "code": "bad_args"}
        if len(args) > 128:
            return {"ok": False, "error": "args too long", "code": "bad_args"}
        for a in args:
            if not isinstance(a, (str, int, float)):
                return {"ok": False, "error": "args must be scalars", "code": "bad_args"}
        if port < 1 or port > 65535:
            return {"ok": False, "error": "invalid port", "code": "bad_port"}
        return None

    def _format_spawn_failure(self, err: BaseException, exe: str) -> dict[str, Any]:
        msg = str(getattr(err, "strerror", None) or err)
        winerror = getattr(err, "winerror", None)
        blocked = os.name == "nt" and (
            winerror in (5, 577, 740)
            or "winerror 5" in msg.lower()
            or "access is denied" in msg.lower()
        )
        if blocked:
            return {
                "ok": False,
                "error": (
                    "无法启动 llama-server：已被 Windows「智能应用控制 / Device Guard」拦截。"
                    "请把应用数据放在 C: 用户目录，或在「Windows 安全中心 → 应用和浏览器控制 "
                    "→ 智能应用控制」中关闭后重试。"
                ),
                "code": "spawn_blocked",
                "exePath": exe,
                "via": "engine",
            }
        return {
            "ok": False,
            "error": f"无法启动 llama-server：{msg}",
            "code": "spawn_failed",
            "exePath": exe,
            "via": "engine",
        }

    def _kill_locked(self) -> None:
        proc = self._proc
        self._proc = None
        if proc is None:
            return
        if proc.poll() is not None:
            return
        try:
            if os.name == "nt":
                _taskkill_tree(proc.pid)
            else:
                proc.send_signal(signal.SIGTERM)
                try:
                    proc.wait(timeout=3)
                except subprocess.TimeoutExpired:
                    proc.kill()
        except Exception:
            try:
                proc.kill()
            except Exception:
                pass

    def _clear_idle_timer_locked(self) -> None:
        timer = self._idle_timer
        self._idle_timer = None
        if timer is not None:
            try:
                timer.cancel()
            except Exception:
                pass

    @staticmethod
    def _is_port_healthy(port: int, timeout_s: float = 2.0) -> bool:
        url = f"http://127.0.0.1:{int(port)}/health"
        try:
            req = urllib.request.Request(url, method="GET")
            with urllib.request.urlopen(req, timeout=timeout_s) as resp:
                return 200 <= int(getattr(resp, "status", 200) or 200) < 300
        except Exception:
            return False

    def _wait_healthy(
        self,
        port: int,
        proc: subprocess.Popen[bytes],
        *,
        timeout_ms: int,
        get_tail: Any,
    ) -> dict[str, Any]:
        started = time.time()
        timeout_s = max(5.0, timeout_ms / 1000.0)
        while time.time() - started < timeout_s:
            if proc.poll() is not None:
                return {
                    "ok": False,
                    "error": f"llama-server 已退出（code {proc.returncode}）",
                    "code": "server_exited",
                }
            tail = str(get_tail() or "")
            if any(
                x in tail.lower()
                for x in (
                    "out of memory",
                    "cuda error",
                    "failed to allocate",
                    "ggml_assert",
                    "cannot allocate",
                )
            ):
                return {
                    "ok": False,
                    "error": "GPU 加载失败（显存不足或 CUDA 错误）",
                    "code": "gpu_load_failed",
                }
            if self._is_port_healthy(port, timeout_s=1.0):
                return {"ok": True}
            time.sleep(0.45)
        return {
            "ok": False,
            "error": "启动超时：模型加载过久或运行时异常",
            "code": "server_timeout",
        }


# Process-wide singleton (one llama-server per engine).
MANAGER = LlamaServerManager()
